const rows = $input.all().map(item => item.json);

const validRows = rows.filter(row =>
  row.metric && row.category && row.value !== null
);


const analysis = {};

for (const row of validRows) {
  if (!analysis[row.metric]) {
    analysis[row.metric] = [];
  }

  analysis[row.metric].push({
    category: row.category,
    value: Number(row.value),
    period: row.period
  });
}

return [
  {
    json: analysis
  }
];

const data = $input.first().json;


const totalSales = Math.max(
  ...(data.total_sales || []).map(item => Number(item.value || 0))
);


function removeDuplicates(rows) {
  const unique = new Map();

  for (const row of rows) {
    const key = `${row.category}-${row.period}`;
    if (!unique.has(key)) {
      unique.set(key, row);
    }
  }

  return [...unique.values()];
}

const productLine = removeDuplicates(data.product_line || []);
const countries = removeDuplicates(data.country || []);
const monthlySales = removeDuplicates(data.monthly_sales || []);
const customers = removeDuplicates(data.top_customer || []);

const topProduct = [...productLine].sort((a, b) => b.value - a.value)[0];
const topCountry = [...countries].sort((a, b) => b.value - a.value)[0];

const formatNumber = value =>
  Number(value || 0).toLocaleString('en-US', {
    maximumFractionDigits: 2
  });


const html = `
<!DOCTYPE html>
<html>
<head>
<meta charset="UTF-8">
<meta name="viewport" content="width=device-width, initial-scale=1">
<title>Sales Analytics Dashboard</title>
<script src="https://cdn.jsdelivr.net/npm/chart.js"></script>

<style>
body {
  font-family: Arial, sans-serif;
  background: #f4f8fc;
  margin: 0;
  padding: 25px;
  color: #1e293b;
}
h1 { color: #1d4ed8; }
.cards {
  display: grid;
  grid-template-columns: repeat(auto-fit, minmax(200px, 1fr));
  gap: 18px;
  margin: 25px 0;
}
.card, .chart {
  background: white;
  padding: 22px;
  border-radius: 12px;
  box-shadow: 0 2px 10px #0000000d;
}
.card {
  border-top: 4px solid #1d4ed8;
  transition: transform 0.2s ease;
}

.card:hover {
  transform: translateY(-4px);
}
.card h3 { color: #777; font-size: 14px; }
.card p { font-size: 22px; font-weight: bold; }
.charts {
  display: grid;
  grid-template-columns: repeat(auto-fit, minmax(350px, 1fr));
  gap: 20px;
}
.chart { min-height: 300px; }
</style>
</head>

<body>
<h1>Sales Analytics Dashboard</h1>
<p>Overview of sales performance</p>
<div style="margin: 20px 0;">
  <label for="monthFilter">Select Month:</label>
  <select id="monthFilter">
    <option value="all">All Months</option>
  </select>
</div>

<div class="cards">
  <div class="card">
    <h3>Total Sales</h3>
    <p>${formatNumber(totalSales)}</p>
  </div>
  <div class="card">
    <h3>Top Product Line</h3>
    <p>${topProduct?.category || 'N/A'}</p>
  </div>
  <div class="card">
    <h3>Top Country</h3>
    <p>${topCountry?.category || 'N/A'}</p>
  </div>
  <div class="card">
    <h3>Top Customer</h3>
    <p>${customers[0]?.category || 'N/A'}</p>
  </div>
</div>

<div class="charts">
  <div class="chart"><canvas id="products"></canvas></div>
  <div class="chart"><canvas id="countries"></canvas></div>
  <div class="chart"><canvas id="monthly"></canvas></div>
  <div class="chart"><canvas id="customers"></canvas></div>
</div>

<script>
const products = ${JSON.stringify(productLine)};
const countries = ${JSON.stringify(countries)};
const monthly = ${JSON.stringify(monthlySales)};
const customers = ${JSON.stringify(customers)};

function createChart(id, type, rows, title) {
  new Chart(document.getElementById(id), {
    type,
    data: {
      labels: rows.map(r => 
  r.period && r.period !== 'All' ? r.period : r.category
),
      datasets: [{
        label: 'Sales',
        data: rows.map(r => r.value),
        backgroundColor: '##60a5fa',
        borderColor: '#1d4ed8',
        borderWidth: 2,
        tension: 0.3
      }]
    },
    options: {
      responsive: true,
      maintainAspectRatio: false,
      plugins: {
        title: { display: true, text: title }
      }
    }
  });
}

createChart('products', 'bar', products, 'Sales by Product Line');
createChart('countries', 'bar', countries, 'Sales by Country');
createChart('monthly', 'line', monthly, 'Monthly Sales');
createChart('customers', 'bar', customers, 'Top 10 Customers');
</script>
</body>
</html>
`;

return [{ json: { html } }];
